sys_script_include.script:
var HSBC_MSS_CheckUser = Class.create();
HSBC_MSS_CheckUser.prototype = {
    initialize: function() {},
    checkroles: function(current) {

        var arr = [];
        if (gs.hasRole('mss_manager') && current.assignment_group.manager == gs.getUserID()) {

            var returngroupmembers = new GlideRecord('sys_user_grmember');
            returngroupmembers.addQuery('group', current.assignment_group);
            returngroupmembers.query();
            while (returngroupmembers.next()) {
                arr.push(returngroupmembers.user.toString());
            }

            return 'sys_idIN' + arr;
        } else if (!(gs.hasRole('mss_manager')) && (gs.hasRole('mss_user')) && (gs.getUser().isMemberOf(current.assignment_group.getDisplayValue()))) {

            return 'sys_idIN' + gs.getUserID();
        } else {
            return 'sys_idIN';
        }
    },
    type: 'HSBC_MSS_CheckUser'
};
